query OrgMetadataDeep($login: String!) {
  rateLimit { cost remaining resetAt }
  organization(login: $login) {
    id
    login
    name
    description
    websiteUrl
    isVerified
    requiresTwoFactorAuthentication
    defaultRepositoryPermission
    membersWithRole { totalCount }
    pendingMembers { totalCount }
    securityManagers(first: 20) {
      nodes { slug name }
    }
    projectsV2(first: 20) {
      nodes {
        id
        title
        fields(first: 20) {
          nodes {
            ... on ProjectV2FieldCommon { id name dataType }
          }
        }
      }
    }
  }
}

query OrgRepositoriesDeep($login: String!, $cursor: String) {
  rateLimit { cost remaining resetAt }
  organization(login: $login) {
    repositories(first: 100, after: $cursor, orderBy: {field: NAME, direction: ASC}) {
      pageInfo { hasNextPage endCursor }
      totalCount
      nodes {
        id
        name
        visibility
        isArchived
        isFork
        diskUsage
        defaultBranchRef { name }
        refs(refPrefix: "refs/heads/", first: 20) {
          nodes { name prefix }
        }
        branchProtectionRules(first: 10) {
          nodes {
            pattern
            requiresApprovingReviews
            requiredApprovingReviewCount
            requiresStatusChecks
            requiresStrictStatusChecks
            requiredStatusCheckContexts
          }
        }
        rulesets(first: 10) {
          nodes {
            name
            enforcement
            target
          }
        }
        languages(first: 10, orderBy: {field: SIZE, direction: DESC}) {
          edges { size node { name } }
        }
        repositoryTopics(first: 10) {
          nodes { topic { name } }
        }
        releases(first: 5) {
          nodes {
            name
            releaseAssets(first: 10) {
              nodes { name size downloadCount }
            }
          }
        }
        packages(first: 10) {
          nodes { name packageType }
        }
      }
    }
  }
}

query OrgTeamsDeep($login: String!, $cursor: String) {
  rateLimit { cost remaining resetAt }
  organization(login: $login) {
    teams(first: 100, after: $cursor, rootTeamsOnly: true) {
      pageInfo { hasNextPage endCursor }
      totalCount
      nodes {
        id
        slug
        name
        description
        members { totalCount }
        childTeams(first: 20) {
          nodes { id slug name members { totalCount } }
        }
        repositories(first: 100) {
          edges {
            permission
            node { id name }
          }
        }
      }
    }
  }
}

query EnterpriseOrgsDeep($slug: String!, $cursor: String) {
  rateLimit { cost remaining resetAt }
  enterprise(slug: $slug) {
    id
    name
    slug
    organizations(first: 100, after: $cursor) {
      pageInfo { hasNextPage endCursor }
      totalCount
      nodes { id login name }
    }
    teams(first: 50) {
      nodes {
        slug
        name
        members { totalCount }
      }
    }
  }
}
